259	    /**
260	     * Rejects an owner payload that is missing or blank in any mandatory field. This complements Bean
261	     * Validation, which cannot reject whitespace-only values that still satisfy a minimum-length constraint.
262	     *
263	     * @param fields the submitted owner fields
264	     * @throws RequiredFieldsMissingException if any of firstName, lastName, city or telephone is
265	     *                                        {@code null} or blank, or if address is blank after
266	     *                                        normalization
267	     */
268	    private void rejectMissingOrBlankFields(OwnerFieldsDto fields) {
269	        List<String> missing = new ArrayList<>();
270	        if (isBlank(fields.getFirstName())) {
271	            missing.add("firstName");
272	        }
273	        if (isBlank(fields.getLastName())) {
274	            missing.add("lastName");
275	        }
276	        if (isBlank(normalizeAddress(fields.getAddress()))) {
277	            missing.add("address");
278	        }
279	        if (isBlank(fields.getCity())) {
280	            missing.add("city");
281	        }
282	        if (isBlank(fields.getTelephone())) {
283	            missing.add("telephone");
284	        }
285	        if (!missing.isEmpty()) {
286	            throw new RequiredFieldsMissingException(missing);
287	        }
288	    }
