294	    /**
295	     * Inclusive 4-digit postcode ranges permitted per city region, keyed by the region derived from the
296	     * city via {@link OwnerLocality}: NSW 2000-2099, VIC 3000-3099, QLD 4000-4099. A region absent from
297	     * this table (i.e. {@code "UNKNOWN"}) imposes no range constraint, so any 4-digit postcode is accepted.
298	     */
299	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
300	        "NSW", new int[] {2000, 2099},
301	        "VIC", new int[] {3000, 3099},
302	        "QLD", new int[] {4000, 4099});
303	
304	    /**
305	     * Validates an owner's {@code postcode} when present. Postcode is optional: a {@code null} value is
306	     * accepted and left absent, keeping the create contract backward-compatible. When supplied it must be
307	     * a 4-digit value, and it must fall within the inclusive range for the city's region (NSW 2000-2099,
308	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
309	     *
310	     * @param postcode the submitted postcode, or {@code null} when omitted
311	     * @param city the owner's city, used to derive the region whose range constrains the postcode
312	     * @throws InvalidPostcodeException if a supplied postcode is not 4 digits or is out of range for the
313	     *                                  city's region
314	     */
315	    private void validatePostcode(String postcode, String city) {
316	        if (postcode == null) {
317	            return;
318	        }
319	        if (!postcode.matches("[0-9]{4}")) {
320	            throw new InvalidPostcodeException(postcode);
321	        }
322	        int[] range = REGION_POSTCODE_RANGE.get(OwnerLocality.of(city));
323	        if (range == null) {
324	            return;
325	        }
326	        int value = Integer.parseInt(postcode);
327	        if (value < range[0] || value > range[1]) {
328	            throw new InvalidPostcodeException(postcode);
329	        }
330	    }
331	
332	    /**
333	     * Normalizes a submitted telephone number into E.164 form, which becomes the stored and returned
334	     * value. Spaces, dashes and brackets are stripped. A leading {@code '+'} and its country code are
335	     * kept as supplied; otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
336	     * is dropped from the national digits. The result must be a {@code '+'} followed by 8 to 15 digits.
337	     * <p>
338	     * Where a per-country rule is defined the national-number length is validated against the country
339	     * code: {@code '+61'} (Australia) requires exactly 9 national digits and {@code '+1'} (NANP)
340	     * requires exactly 10.
341	     *
342	     * @param telephone the raw telephone value from the request
343	     * @return the E.164 telephone (a {@code '+'} followed by 8 to 15 digits)
344	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
345	     */
346	    private String normalizeTelephone(String telephone) {
347	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s()\\-]", "");
348	        String digits;
349	        if (cleaned.startsWith("+")) {
350	            digits = cleaned.substring(1);
351	        } else {
352	            // No country code supplied: assume Australia (+61) and drop a single leading '0'.
353	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
354	            digits = "61" + national;
355	        }
356	        if (!digits.matches("[0-9]{8,15}")) {
357	            throw new InvalidTelephoneException(cleaned);
358	        }
359	        // Validate the national-number length against the country code where a rule is defined.
360	        if (digits.startsWith("61") && digits.length() - 2 != 9) {
361	            throw new InvalidTelephoneException(cleaned);
362	        }
363	        if (digits.startsWith("1") && digits.length() - 1 != 10) {
364	            throw new InvalidTelephoneException(cleaned);
365	        }
366	        return "+" + digits;
367	    }
368	
369	    /**
370	     * Normalizes a submitted email address. A {@code null} email is left absent (the field is optional).
371	     * When present, it must be a syntactically valid address; the stored and returned value is trimmed and
372	     * lower-cased.
373	     *
374	     * @param email the raw email value from the request, or {@code null} if omitted
375	     * @return the lower-cased email, or {@code null} if none was supplied
376	     * @throws InvalidEmailException if a non-null email is not a syntactically valid address
377	     */
378	    private String normalizeEmail(String email) {
379	        if (email == null) {
380	            return null;
381	        }
382	        String trimmed = email.strip();
383	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
384	            throw new InvalidEmailException(email);
385	        }
386	        return trimmed.toLowerCase(Locale.ROOT);
387	    }
388	
389	    /**
390	     * Normalizes a submitted address into the form that is stored and returned. Leading and trailing
391	     * whitespace is removed, internal runs of whitespace are collapsed to a single space, the value is
392	     * upper-cased, and common street-type abbreviations are expanded ({@code ST -> STREET},
393	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). Abbreviations are only expanded when they form a whole
394	     * word, so an address such as {@code '  12  main  st '} normalizes to {@code '12 MAIN STREET'}.
395	     *
396	     * @param address the raw address value from the request (may be {@code null})
397	     * @return the normalized address, or an empty string when {@code address} is {@code null} or blank
398	     */
399	    private String normalizeAddress(String address) {
400	        if (address == null) {
401	            return "";
402	        }
403	        String collapsed = address.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
404	        if (collapsed.isEmpty()) {
405	            return "";
406	        }
407	        String[] tokens = collapsed.split(" ");
408	        StringBuilder sb = new StringBuilder(collapsed.length());
409	        for (int i = 0; i < tokens.length; i++) {
410	            if (i > 0) {
411	                sb.append(' ');
412	            }
413	            sb.append(expandAddressAbbreviation(tokens[i]));
414	        }
415	        return sb.toString();
416	    }
417	
418	    /**
419	     * Expands a single upper-cased address token from its common abbreviation to its full form, or
420	     * returns the token unchanged when it is not a recognised abbreviation.
421	     *
422	     * @param token an upper-cased whole-word address token
423	     * @return the expanded form ({@code STREET}, {@code ROAD}, {@code AVENUE}) or the original token
424	     */
425	    private String expandAddressAbbreviation(String token) {
426	        return switch (token) {
427	            case "ST" -> "STREET";
428	            case "RD" -> "ROAD";
429	            case "AVE" -> "AVENUE";
430	            default -> token;
431	        };
432	    }
433	
434	    /**
435	     * Builds the customer code assigned to a newly created owner, formatted {@code '<REGION>-<HASH8>'}
436	     * where {@code REGION} is the region derived from the owner's postcode (falling back to the city when
437	     * the postcode resolves to no known region), the same derivation that yields the owner's locality, and
438	     * {@code HASH8} is the first 8 upper-cased hex characters of the SHA-256 digest of the owner's
439	     * normalized telephone concatenated with the owner's last name (e.g. {@code 'NSW-1A2B3C4D'}). Unlike the
440	     * former per-city sequence, the code is a pure function of the owner's own region and identity, so no
441	     * sequence number is assigned.
442	     *
443	     * @param owner the owner being created, with normalized telephone and postcode already set
444	     * @return the assigned customer code
445	     */
446	    private String generateCustomerCode(Owner owner) {
447	        String region = OwnerLocality.of(owner.getCity(), owner.getPostcode());
448	        String hash8 = sha256Hex(owner.getTelephone() + owner.getLastName())
449	            .substring(0, 8).toUpperCase(Locale.ROOT);
450	        return region + "-" + hash8;
451	    }
452	
453	    /**
454	     * Computes the full lower-case hex SHA-256 digest of the UTF-8 bytes of the given value.
455	     *
456	     * @param value the value to hash
457	     * @return the 64-character lower-case hex SHA-256 digest
458	     */
459	    private String sha256Hex(String value) {
460	        try {
461	            byte[] digest = MessageDigest.getInstance("SHA-256")
462	                .digest(value.getBytes(StandardCharsets.UTF_8));
463	            StringBuilder sb = new StringBuilder(digest.length * 2);
464	            for (byte b : digest) {
465	                sb.append(String.format("%02x", b));
466	            }
467	            return sb.toString();
468	        } catch (NoSuchAlgorithmException e) {
469	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
470	        }
471	    }
472	
473	    /**
474	     * Counts how many existing owners already share the given first name and last name, compared
475	     * case-insensitively. The count is taken before the new owner is persisted, so it excludes the
476	     * owner being created.
477	     *
478	     * @param firstName the first name of the owner being created
479	     * @param lastName the last name of the owner being created
480	     * @return the number of existing owners with the same first and last name (case-insensitively)
481	     */
482	    private int countNamesakes(String firstName, String lastName) {
483	        return (int) this.clinicService.findAllOwners().stream()
484	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
485	                && lastName.equalsIgnoreCase(existing.getLastName()))
486	            .count();
487	    }
488	
489	    /**
490	     * The maximum number of owners permitted in a single city. A create request whose city already
491	     * holds this many owners is rejected.
492	     */
493	    private static final int CITY_OWNER_LIMIT = 50;
494	
495	    /**
496	     * Rejects a create request whose city already contains {@link #CITY_OWNER_LIMIT} or more owners.
497	     * Cities are matched case-insensitively, mirroring the per-city customer-code sequence, so owners
498	     * differing only in the casing of their city share one capacity pool. The count is taken before the
499	     * new owner is persisted, so it excludes the owner being created.
500	     *
501	     * @param city the city of the owner being created
502	     * @throws CityOwnerLimitExceededException if the city already holds the maximum number of owners
503	     */
504	    private void rejectCityAtCapacity(String city) {
505	        long existing = this.clinicService.findAllOwners().stream()
506	            .filter(owner -> city.equalsIgnoreCase(owner.getCity()))
507	            .count();
508	        if (existing >= CITY_OWNER_LIMIT) {
509	            throw new CityOwnerLimitExceededException(city, CITY_OWNER_LIMIT);
510	        }
511	    }
512	
513	    /**
514	     * The maximum number of owners permitted to be created in a single day. A create request whose
515	     * registration date already holds this many owners is rejected.
516	     */
517	    private static final int DAILY_OWNER_LIMIT = 100;
518	
519	    /**
520	     * Rejects a create request when {@link #DAILY_OWNER_LIMIT} or more owners have already been created
521	     * on the same day, compared by {@code registrationDate}. The count is taken before the new owner is
522	     * persisted, so it excludes the owner being created.
523	     *
524	     * @param registrationDate the registration date of the owner being created
525	     * @throws DailyOwnerLimitExceededException if the day already holds the maximum number of owners
526	     */
527	    /**
528	     * Adjusts an effective registration date so that it always falls on a business day. When the given
529	     * date is a Saturday or Sunday it is rolled forward to the following Monday; a weekday is returned
530	     * unchanged. This applies equally to a date supplied in the request and to a date defaulted to the
531	     * server date, and the adjusted value is what becomes the owner's {@code registrationDate}, so every
532	     * value derived from it (the membership number's year segment, the daily create-limit count) uses the
533	     * business-day-adjusted date.
534	     *
535	     * @param date the effective registration date, supplied or defaulted
536	     * @return the same date when it is a weekday, otherwise the next Monday
537	     */
538	    private LocalDate rollToBusinessDay(LocalDate date) {
539	        DayOfWeek day = date.getDayOfWeek();
540	        if (day == DayOfWeek.SATURDAY) {
541	            return date.plusDays(2);
542	        }
543	        if (day == DayOfWeek.SUNDAY) {
544	            return date.plusDays(1);
545	        }
546	        return date;
547	    }
548	
549	    /**
550	     * The number of owners that must already exist for a given day before a further create is flagged as a
551	     * bulk sign-up surge. When more than this many owners already share the new owner's registration date,
552	     * the created owner carries {@code bulkSignupWarning = true}.
553	     */
554	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
555	
556	    /**
557	     * Determines whether the owner being created lands on a day that already holds a bulk sign-up surge,
558	     * i.e. more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already share its {@code registrationDate}.
559	     * The count is taken before the new owner is persisted, so it excludes the owner being created, mirroring
560	     * the daily create-limit rule's accumulation path.
561	     *
562	     * @param registrationDate the registration date of the owner being created
563	     * @return {@code true} when more than 80 owners were already created on that day, otherwise {@code false}
564	     */
565	    private boolean isBulkSignupDay(LocalDate registrationDate) {
566	        long existing = this.clinicService.findAllOwners().stream()
567	            .filter(owner -> registrationDate.equals(owner.getRegistrationDate()))
568	            .count();
569	        return existing > BULK_SIGNUP_WARNING_THRESHOLD;
570	    }
571	
572	    /**
573	     * Rejects a create request whose supplied {@code registrationDate} is later than the server date. A
574	     * registration cannot be dated in the future. The check applies only to a date supplied in the request;
575	     * a {@code null} value (which is later defaulted to the server date) is accepted, and the comparison is
576	     * made against the supplied value before any business-day adjustment.
577	     *
578	     * @param registrationDate the registration date supplied in the request, or {@code null} when omitted
579	     * @throws FutureRegistrationDateException if a supplied registration date is later than the server date
580	     */
581	    private void rejectFutureRegistrationDate(LocalDate registrationDate) {
582	        if (registrationDate == null) {
583	            return;
584	        }
585	        LocalDate today = LocalDate.now();
586	        if (registrationDate.isAfter(today)) {
587	            throw new FutureRegistrationDateException(registrationDate, today);
588	        }
589	    }
590	
591	    private void rejectDailyLimitReached(LocalDate registrationDate) {
592	        long existing = this.clinicService.findAllOwners().stream()
593	            .filter(owner -> registrationDate.equals(owner.getRegistrationDate()))
594	            .count();
595	        if (existing >= DAILY_OWNER_LIMIT) {
596	            throw new DailyOwnerLimitExceededException(registrationDate, DAILY_OWNER_LIMIT);
597	        }
598	    }
599	
600	    /**
601	     * Rejects a create request whose owner collides with an existing owner on the single derived
602	     * {@code identityKey}. This one key consolidates the former separate telephone, email and household
603	     * duplicate checks: the create is rejected only when the new owner's WHOLE identity key exactly equals
604	     * an existing owner's. Because the (normalized) telephone is part of the key, two members of the same
605	     * household (same {@code householdId}) with different telephones have different keys and are both
606	     * allowed; only an exact full-key match is a duplicate. The owner's {@code householdId} must already
607	     * have been assigned (when {@code sharesHousehold} was requested) before this check runs, so the key
608	     * compared here is the same one that is later returned.
609	     *
610	     * @param owner the owner being created, with normalized fields and any shared {@code householdId} set
611	     * @throws DuplicateIdentityException if an existing owner has the same identity key
612	     */
613	    private void rejectDuplicateIdentity(Owner owner) {
614	        String key = identityKey(owner);
615	        boolean taken = this.clinicService.findAllOwners().stream()
616	            .anyMatch(existing -> key.equals(identityKey(existing)));
617	        if (taken) {
618	            throw new DuplicateIdentityException(key);
619	        }
620	    }
621	
622	    /**
623	     * Derives an owner's {@code identityKey}: the normalized telephone, the email (or an empty string when
624	     * absent) and the household id (or an empty string when absent), joined by {@code '|'} in that order
625	     * (e.g. {@code '+61412345678||a1b2c3d4e5f6a7b8'} for an owner with no email but a shared household).
626	     * Telephone and email are stored already normalized, so the stored values are used directly.
627	     *
628	     * @param owner the owner whose identity key is being derived
629	     * @return the owner's identity key
630	     */
631	    private String identityKey(Owner owner) {
632	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
633	        String email = owner.getEmail() == null ? "" : owner.getEmail();
634	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
635	        return telephone + "|" + email + "|" + householdId;
636	    }
637	
638	    /**
639	     * Assigns the owner being created into a shared household. When at least one existing owner has the
640	     * same last name and address (compared with {@link #normalizeForComparison}), the joining owner and
641	     * those existing owners are all given the same stable {@code householdId}. An existing member's id is
642	     * reused when present; otherwise a deterministic id derived from the household's last name and address
643	     * is minted, so independently created members of the same household converge on one value. When no
644	     * existing owner shares the household, no id is assigned (the owner simply founds a new address).
645	     *
646	     * @param owner the owner being created, already opted in via {@code sharesHousehold}
647	     */
648	    private void assignHousehold(Owner owner) {
649	        String normalizedLastName = normalizeForComparison(owner.getLastName());
650	        String normalizedAddress = normalizeForComparison(owner.getAddress());
651	        List<Owner> housemates = this.clinicService.findAllOwners().stream()
652	            .filter(existing -> normalizedLastName.equals(normalizeForComparison(existing.getLastName()))
653	                && normalizedAddress.equals(normalizeForComparison(existing.getAddress())))
654	            .toList();
655	        if (housemates.isEmpty()) {
656	            return;
657	        }
658	        String householdId = housemates.stream()
659	            .map(Owner::getHouseholdId)
660	            .filter(id -> id != null && !id.isBlank())
661	            .findFirst()
662	            .orElseGet(() -> householdIdFor(normalizedLastName, normalizedAddress));
663	        owner.setHouseholdId(householdId);
664	        for (Owner housemate : housemates) {
665	            if (!householdId.equals(housemate.getHouseholdId())) {
666	                housemate.setHouseholdId(householdId);
667	                this.clinicService.saveOwner(housemate);
668	            }
669	        }
670	    }
671	
672	    /**
673	     * Derives a stable household identifier from the normalized last name and address of a household, as
674	     * the first 16 hex characters of the SHA-256 digest of {@code '<lastName>|<address>'}. The value is
675	     * deterministic, so any owner independently joining the same household computes the same identifier.
676	     *
677	     * @param normalizedLastName the household's last name, already normalized for comparison
678	     * @param normalizedAddress the household's address, already normalized for comparison
679	     * @return a stable, shareable household identifier
680	     */
681	    private String householdIdFor(String normalizedLastName, String normalizedAddress) {
682	        String key = normalizedLastName + "|" + normalizedAddress;
683	        return sha256Hex(key).substring(0, 16);
684	    }
685	
686	    /**
687	     * Normalizes a value for household-identity comparison: leading and trailing whitespace is
688	     * removed, internal runs of whitespace are collapsed to a single space, and the result is
689	     * lower-cased.
690	     *
691	     * @param value the raw value to normalize (may be {@code null})
692	     * @return the normalized value, or an empty string when {@code value} is {@code null}
693	     */
694	    private String normalizeForComparison(String value) {
695	        if (value == null) {
696	            return "";
697	        }
698	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
699	    }
700	}
